/**
 * Content of the DeepOCR project report.
 *
 * Result tables are read from results/ so every number matches the evaluation files.
 * Markup: **bold**, *italic*, «monospace», {fig:id} {tab:id} {eq:id} references.
 */
const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..", "..");
const read = (rel) => JSON.parse(fs.readFileSync(path.join(ROOT, rel), "utf8"));
const summary = read("results/evaluation/summary.json").models;
const ensemble = read("results/evaluation/ensemble.json");
const robustness = read("results/evaluation/robustness.json");
const history = {
  cnn_bilstm: read("results/training/cnn_bilstm_history.json"),
  crnn: read("results/training/crnn_history.json"),
  trocr_ft: read("results/training/trocr_ft_history.json"),
};

const f2 = (v) => v.toFixed(2);
const f1 = (v) => v.toFixed(1);
const ms = (v) => (v >= 1000 ? `${(v / 1000).toFixed(2)} s` : `${Math.round(v)} ms`);
const avgMs = (id) => (summary[id].iam.ms_per_line + summary[id].synthetic.ms_per_line) / 2;

const P = (text, extra = {}) => ({ type: "p", text, ...extra });
const H2 = (text) => ({ type: "h2", text });
const H3 = (text) => ({ type: "h3", text });
const UL = (items) => ({ type: "bullets", items });
const OL = (items) => ({ type: "numbers", items });
const FIG = (id, file, caption, width = 1, extra = {}) => ({ type: "figure", id, file, caption, width, ...extra });
const TAB = (id, caption, headers, rows, widths, align, extra = {}) => ({ type: "table", id, caption, headers, rows, widths, align, ...extra });
const EQ = (id, text) => ({ type: "eq", id, text });
const CODE = (title, lines) => ({ type: "code", title, lines });

/* ====================================================================== meta */
const meta = {
  title: "Deep Learning-Based Intelligent OCR System for Handwritten and Complex Document Recognition",
  subtitle: "DeepOCR: preprocessing, text detection, deep-learning recognition, consensus voting, layout analysis and error correction in one system",
  runningHead: "DeepOCR: Intelligent OCR for Handwritten and Complex Documents",
  titleLines: ["October 2026"],
};

/* ====================================================================== front matter */
